arguments.argument:
menu_create(40, 100, 248, 200, 32);

//menumode = true;

if (room != Menu)
    menu_setdimmed();

menu_background(256, 24, 8, 12, 4);
//bgtabs = true;

if (room == Menu)
{
    menu_addlink("Play Replay", '
        if (ds_list_empty(global.replayPlaybackQueue))
        {
            if (replay_queue_add(true, false))
                instance_destroy();
        }
        else
        {
            replay_play_file();
            instance_destroy();
        }
    ');

    menu_addlink("Queue Replay", '
        replay_queue_add(false, false)
    ');

    menu_addlink("Queue Replays From Folder", '
        replay_queue_add(false, true)
    ');

    menu_addlink("Clear Queue", '
        ds_list_clear(global.replayPlaybackQueue);
    ');
}

if (room != Menu and global.isHost and !global.recordingReplay)
{
    menu_addlink("Record Replay", '
        replay_record();
        instance_destroy();
        instance_create(0, 0, ReplayMenuController);
    ');
}

if (room != Menu and global.recordingReplay)
{
    menu_addlink("Stop Recording", '
        replay_stop_recording(false);
        instance_destroy();
        instance_create(0, 0, ReplayMenuController);
    ');
}

if (room != Menu and global.playingReplay)
{
    menu_divider("Playback Controls");

    /*menu_addlink("Show Replay UI", '
        instance_destroy();
    ');*/

    if (!global.replayPaused)
    {
        menu_addlink("Pause Replay", '
            global.replayPaused = true;
            instance_destroy();
            instance_create(0, 0, ReplayMenuController);
        ');
    }
    else
    {
        menu_addlink("Resume Replay", '
            global.replayPaused = false;
            instance_destroy();
            instance_create(0, 0, ReplayMenuController);
        ');
    }

    // TODO: Add controls to skip forward in the replay by fixed and/or custom amounts of time

    menu_addedit_num_percent("Timescale:", "global.replayTimescale", '');

    menu_divider("Replay Queue");

    menu_addlink("Queue Replay", '
        if (replay_queue_add(false, false))
            instance_destroy();
    ');

    menu_addlink("Queue Replays From Folder", '
        if (replay_queue_add(false, true))
            instance_destroy();
    ');

    menu_addlink("Clear Queue", '
        ds_list_clear(global.replayPlaybackQueue);
    ');

    menu_divider("");

    if (!ds_list_empty(global.replayPlaybackQueue))
    {
        menu_addlink("Next Replay", '
            replay_playback_end();
            instance_destroy();
        ');
    }

    menu_addlink("Exit Replay Playback", '
        ds_list_clear(global.replayPlaybackQueue);
        replay_playback_end();
        instance_destroy();
    ');
}

menu_addback("Back", '
    instance_destroy();
    if(room == Menu)
        instance_create(0,0,MainMenuController);
    else
        instance_create(0,0,InGameMenuController);
');
